// server/lib/periodic-table-data.js
//
// Curated periodic table of the elements — all 118 elements currently
// recognized by IUPAC (Z=1 Hydrogen through Z=118 Oganesson). Backs the
// materials.element-list / materials.element-detail macros and the
// PeriodicTable frontend component. This is a pure, static reference
// dataset — no external network call, no LLM, no randomness.
//
// SOURCES (cited, not invented):
//  - IUPAC "Standard Atomic Weights" (2021 table) —
//    https://iupac.org/what-we-do/periodic-table-of-elements/
//    for standardAtomicWeight, and for which elements have NO conventional
//    atomic weight (radioactive elements with no fixed terrestrial isotopic
//    composition are given by IUPAC convention as the mass number of their
//    longest-lived known isotope in square brackets — see
//    massNumberOfLongestLivedIsotope below).
//  - NIST Atomic Weights and Isotopic Compositions —
//    https://www.nist.gov/pml/atomic-weights-and-isotopic-compositions-relative-atomic-masses
//  - CRC Handbook of Chemistry and Physics reference values for density /
//    melting point / boiling point / electron configuration, as aggregated
//    per-element (with Wikipedia infobox citations back to CRC/NIST/IUPAC)
//    in the Bowserinator/Periodic-Table-JSON dataset (MIT license) —
//    https://github.com/Bowserinator/Periodic-Table-JSON
//    — cross-checked against IUPAC/NIST for atomic number, symbol, standard
//    atomic weight, and group/period/block placement before curation here.
//
// HONESTY RULE (this is the load-bearing part — see CLAUDE.md "honest by
// construction"): elements Z=104 (Rutherfordium) through Z=118 (Oganesson)
// have NEVER had a macroscopic (weighable) sample produced — every atom of
// these 15 elements ever synthesized has decayed within milliseconds to
// minutes, one atom (or a small handful) at a time. Density, melting point,
// and boiling point are therefore `null` for all of them
// (`unmeasuredBulkProperties: true`) — not because this module forgot to
// fill them in, but because no authoritative measured value exists to cite,
// and this dataset does not publish invented numbers to fill the gap.
// Six further elements — Astatine (85), Francium (87), Fermium (100),
// Mendelevium (101), Nobelium (102), Lawrencium (103) — have also never
// been isolated in weighable quantity; where a value IS listed for them it
// is a long-standing *published estimate* extrapolated from periodic
// trends, not a direct measurement, flagged `predictedNotMeasured: true`.
// Some individual properties for these six are themselves null (e.g. no
// published boiling-point estimate exists for Fm/Md/No/Lr) — that gap is
// carried through as null rather than filled in.
// Carbon, Phosphorus, and Arsenic show `meltingPointC: null` for an
// unrelated, equally honest reason: at 1 atm they sublime/decompose rather
// than passing through a conventional liquid melting transition, so no
// single 1-atm melting point is defined for them (Carbon's ~4300K melting
// point requires ~10+ MPa and is not a 1-atm figure).
//
// Field notes:
//  - standardAtomicWeight: IUPAC conventional atomic weight, or null when
//    the element has no natural/conventional value (see massNumberOf...).
//  - massNumberOfLongestLivedIsotope: set only when standardAtomicWeight is
//    null — the mass number (not a weighted average) of the longest-lived
//    known isotope, per IUPAC's bracket-notation convention.
//  - density: numeric value in the unit given by densityUnit (gases are
//    conventionally reported in g/L at 0C/1atm, not g/cm3, because the
//    g/cm3 figure would round to three leading zeros for every gas).
//  - gridCol / gridRow: 1-indexed placement in the classic 18-column x
//    10-row periodic table layout (rows 9-10 are the lanthanide/actinide
//    footnote rows; row 8 is the spacer row above them).
//  - category: the descriptive block/family name. Several Z>=109 entries
//    read "unknown, probably ..." / "unknown, predicted to be ..." verbatim
//    — that hedge is itself the honest, cited scientific consensus for
//    elements whose chemistry has not been experimentally confirmed.

