export const ELEMENT_BY_NUMBER = new Map(ELEMENTS.map((e) => [e.z, e]));
export const ELEMENT_BY_SYMBOL = new Map(ELEMENTS.map((e) => [e.symbol.toLowerCase(), e]));

// Coarse coloring/legend bucket for the frontend grid. Derived from the
// cited `category` string rather than hand-duplicated per element, so it
// can never drift out of sync with the source data above.
export function categoryGroup(category) {
  const c = String(category || '').toLowerCase();
  if (c.includes('alkaline earth')) return 'alkaline-earth-metal';
  if (c.includes('alkali metal')) return 'alkali-metal';
  if (c.includes('lanthanide')) return 'lanthanide';
  if (c.includes('actinide')) return 'actinide';
  if (c.includes('noble gas')) return 'noble-gas';
  if (c.includes('metalloid')) return 'metalloid';
  if (c.includes('post-transition')) return 'post-transition-metal';
  if (c.includes('transition metal')) return 'transition-metal';
  if (c.includes('nonmetal')) return 'nonmetal';
  return 'unknown';
}

export function getElement(query) {
  if (query == null) return null;
  if (typeof query === 'number') return ELEMENT_BY_NUMBER.get(query) || null;
  const s = String(query).trim();
  if (/^\d+$/.test(s)) return ELEMENT_BY_NUMBER.get(Number(s)) || null;
  return ELEMENT_BY_SYMBOL.get(s.toLowerCase()) || null;
}

